mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM `user`
    WHERE email = #{email}
)

SELECT DISTINCT u.user_id, u.email, u.name, u.phone, u.role, u.account_status, u.created_at FROM `user` u INNER JOIN user_site us ON us.user_id = u.user_id INNER JOIN site s ON s.site_id = us.site_id WHERE us.site_id = #{siteId} AND us.deleted_at IS NULL AND s.deleted_at IS NULL AND u.deleted_at IS NULL AND u.account_status = 'ACTIVE' AND u.role IN
#{role}
ORDER BY u.user_id DESC

SELECT DISTINCT u.user_id, u.email, u.name, u.phone, u.role, u.account_status, u.created_at FROM `user` u INNER JOIN user_site us ON us.user_id = u.user_id INNER JOIN site s ON s.site_id = us.site_id WHERE us.site_id = #{siteId} AND us.deleted_at IS NULL AND s.deleted_at IS NULL AND u.deleted_at IS NULL AND u.account_status = 'ACTIVE' AND u.role IN
#{role}
AND ( u.name LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY u.user_id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(DISTINCT u.user_id) FROM `user` u INNER JOIN user_site us ON us.user_id = u.user_id INNER JOIN site s ON s.site_id = us.site_id WHERE us.site_id = #{siteId} AND us.deleted_at IS NULL AND s.deleted_at IS NULL AND u.deleted_at IS NULL AND u.account_status = 'ACTIVE' AND u.role IN
#{role}
AND ( u.name LIKE CONCAT('%', #{keyword}, '%') OR u.email LIKE CONCAT('%', #{keyword}, '%') OR u.phone LIKE CONCAT('%', #{keyword}, '%') )

